import{_ as e,H as a,f as n,i as s}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"08 | 事实比较：如何快速比较目标与结果？","description":"","frontmatter":{},"headers":[{"level":2,"title":"事实的组成","slug":"事实的组成","link":"#事实的组成","children":[]},{"level":2,"title":"目标的来源","slug":"目标的来源","link":"#目标的来源","children":[]},{"level":2,"title":"SMART原则","slug":"smart原则","link":"#smart原则","children":[]},{"level":2,"title":"填写结果","slug":"填写结果","link":"#填写结果","children":[]},{"level":2,"title":"对齐","slug":"对齐","link":"#对齐","children":[]},{"level":2,"title":"SCQA架构","slug":"scqa架构","link":"#scqa架构","children":[{"level":3,"title":"1. 标准式","slug":"_1-标准式","link":"#_1-标准式","children":[]},{"level":3,"title":"2. 开门见山式","slug":"_2-开门见山式","link":"#_2-开门见山式","children":[]},{"level":3,"title":"3. 突出忧虑式","slug":"_3-突出忧虑式","link":"#_3-突出忧虑式","children":[]},{"level":3,"title":"4. 突出信心式","slug":"_4-突出信心式","link":"#_4-突出信心式","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"跟着高手学复盘/08-事实比较：如何快速比较目标与结果？.md","filePath":"跟着高手学复盘/08-事实比较：如何快速比较目标与结果？.md","lastUpdated":1779822456000}'),r={name:"跟着高手学复盘/08-事实比较：如何快速比较目标与结果？.md"};function i(o,t,p,l,g,h){return a(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_08-事实比较-如何快速比较目标与结果" tabindex="-1">08 | 事实比较：如何快速比较目标与结果？ <a class="header-anchor" href="#_08-事实比较-如何快速比较目标与结果" aria-label="Permalink to &quot;08 | 事实比较：如何快速比较目标与结果？&quot;">​</a></h1><p>你好，我是张鹏。</p><p>上一讲我为你介绍了召开高效复盘会议的“五步法”，带你了解了复盘会议的标准流程。其实五步法如果不算第一步破冰的话，第二步到第五步刚好对应CLAP模型的四个环节。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E7%9D%80%E9%AB%98%E6%89%8B%E5%AD%A6%E5%A4%8D%E7%9B%98/images/344511/20da4984663bbc9e4dba187b4959yye6.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E7%9D%80%E9%AB%98%E6%89%8B%E5%AD%A6%E5%A4%8D%E7%9B%98/images/344511/20da4984663bbc9e4dba187b4959yye6.jpg" alt=""></a></p><p>复盘的基石部分就是 <strong>对比</strong>，也就是事实比较，毕竟如果脱离事实，一切都是空谈。</p><p>事实比较这一步听起来好像很简单，但实际上做起来还是有一定难度的。这一讲我就会和你分享事实比较的方法。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E7%9D%80%E9%AB%98%E6%89%8B%E5%AD%A6%E5%A4%8D%E7%9B%98/images/344511/0e196ab747fba2f541d34078705e339e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E7%9D%80%E9%AB%98%E6%89%8B%E5%AD%A6%E5%A4%8D%E7%9B%98/images/344511/0e196ab747fba2f541d34078705e339e.jpg" alt=""></a></p><h2 id="事实的组成" tabindex="-1">事实的组成 <a class="header-anchor" href="#事实的组成" aria-label="Permalink to &quot;事实的组成&quot;">​</a></h2><p>首先，我们要搞清楚事实包括什么，其实它由目标和结果两个部分组成。</p><p><strong>目标</strong> 可以分为两种，一种是 <strong>数据型目标</strong>（Goal），比较容易用数据进行衡量，比如经营数据、运营数据、技术参数等，相对客观和简单；另一种是 <strong>里程碑型目标</strong>（Objective），不太容易用数字进行衡量，一般需要用文字来进行描述，比如“新产品研发获得重大突破”等。</p><p><strong>结果</strong>（Result）的情况往往会更复杂，大多数情况下最终的结果和当初设定的目标不太一样。</p><p>有些时候你会看到，有的结果和目标是可以进行比较的，比如超出了目标，或者没有达成目标。</p><p>还有些时候，因为某些原因，原来制定的目标“消失”了，或者产生的结果不在原定的目标设定范围之内。这时候，我们就要看实际的结果和项目的战略战术方向是否保持一致了。</p><h2 id="目标的来源" tabindex="-1">目标的来源 <a class="header-anchor" href="#目标的来源" aria-label="Permalink to &quot;目标的来源&quot;">​</a></h2><p>关于目标，我们要思考两个关键问题：</p><ol><li>目标从哪里来？或者说，目标是如何制定的？</li><li>目标制定得合理合规吗？</li></ol><p>如果清楚了这两个问题的答案，你将获得鸟瞰全局的视野，无论你在职场的任何阶段，都能 <strong>“做正确的事”，</strong> 而不仅仅是“ <strong>正确地做事</strong>”。这样你就能够事半功倍，更容易获得晋升的机会。</p><p>公司的本质是一个商业组织，通过 <strong>创造价值</strong> 和 <strong>价值变现</strong> 来实现生存发展。一个公司如果想要有长久的生命力，就一定要有使命、愿景、价值观、战略、目标、结果和行动计划这样的东西，如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E7%9D%80%E9%AB%98%E6%89%8B%E5%AD%A6%E5%A4%8D%E7%9B%98/images/344511/717f90e8e29bd78a9c66307fd9135d14.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E7%9D%80%E9%AB%98%E6%89%8B%E5%AD%A6%E5%A4%8D%E7%9B%98/images/344511/717f90e8e29bd78a9c66307fd9135d14.jpg" alt=""></a></p><blockquote><p>使命是我们（公司）存在的意义，即我们解决了什么社会性、市场性的问题。</p><p>愿景是我们的未来是什么样子？比如：成为行业领导者，最佳产品提供商、受人尊敬的雇主等等。</p><p>价值观是保证我们完成使命愿景所提倡和反对的底线原则。</p><p>战略是实现愿景的方向、中长期规划、策略等。</p><p>目标是实现战略近期需要聚焦达成的具体事项。</p><p>关键结果是如何知道我们在向目标推进。</p><p>行动计划是实现关键结果的行动序列。</p></blockquote><p>从图中可以看到，目标是上承战略，下接行动的。 <strong>目标与战略的匹配度，基本上可以反映出这个目标好还是不好。</strong> 它既是目标制定的标准，也是目标的审视标准。</p><p>了解这一点，你就不再是只能被动接受目标的小白了，而是已经有足够的能力去区分目标的好坏优劣，去“做正确的事”。</p><p>如果目标 <strong>和战略的匹配度可以定性</strong> 目标的好与坏，那目标的制定是否 <strong>符合SMART原则则是定量</strong> 了。</p><h2 id="smart原则" tabindex="-1">SMART原则 <a class="header-anchor" href="#smart原则" aria-label="Permalink to &quot;SMART原则&quot;">​</a></h2><p>如果公司很重视客户服务，那么客服部门的目标如果定成“增强客户服务意识”就很不明确，而定成“一个季度内，把客户满意度提升至95%”或者“1个季度内，在满意度不变的情况下，把客户响应时间缩短到2小时内”就更为精准和易于理解。</p><p>SMART是由5个英文单词的首字母构成，它们分别是：</p><ul><li><strong>Specific</strong>：目标必须是具体的。</li><li><strong>Measurable</strong>：目标是可以被衡量的。</li><li><strong>Attainable/Aspirational</strong>：目标是可达成的/目标是有野心的。</li><li><strong>Relevant</strong>：和其他目标的相关性。</li><li><strong>Time-bound</strong>：目标是要有时间截止点的。</li></ul><p>其中A有两种，这里补充说明一下：如果是确定性的目标，用KPI考核的，那么A就是 <strong>Attainable</strong>，强调 <strong>可达成</strong>；如果是不确定的目标，用OKR管理的，比如创新项目，那么A就是 <strong>Aspirational</strong>（有野心的），强调 <strong>高挑战</strong>。</p><p>用一句话来说，SMART原则可以这么理解：要干什么？结果是什么？条件是什么？什么时间完成？</p><h2 id="填写结果" tabindex="-1">填写结果 <a class="header-anchor" href="#填写结果" aria-label="Permalink to &quot;填写结果&quot;">​</a></h2><p>看完目标，我们这里再看看结果。</p><p>对于 <strong>数据型目标的结果</strong>，我总结了一个快速对比表格工具。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E7%9D%80%E9%AB%98%E6%89%8B%E5%AD%A6%E5%A4%8D%E7%9B%98/images/344511/e08b03ef0d9ff0163767ff9fc9ab747e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E7%9D%80%E9%AB%98%E6%89%8B%E5%AD%A6%E5%A4%8D%E7%9B%98/images/344511/e08b03ef0d9ff0163767ff9fc9ab747e.jpg" alt=""></a></p><p>比如，某公司开发了三种产品A\\B\\C，期待的销售额分别都是100万，针对的是不同的客群比如：品牌企业客户、非品牌企业客户、个人客户。而最后的结果是：A产品销售了200万，B产品销售额是50万，C产品销售额是5万，填入上述表格之后，就是：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E7%9D%80%E9%AB%98%E6%89%8B%E5%AD%A6%E5%A4%8D%E7%9B%98/images/344511/7f7797d75fa72763651ca6d64684fdc3.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E7%9D%80%E9%AB%98%E6%89%8B%E5%AD%A6%E5%A4%8D%E7%9B%98/images/344511/7f7797d75fa72763651ca6d64684fdc3.jpg" alt=""></a></p><p>这个数据highlight出来之后，就会在下一步的逻辑分析中，进一步分析ABC卖得好还是不好的原因到底是什么。</p><p>对于 <strong>里程碑型目标的结果</strong>，我们可以用 <a href="https://time.geekbang.org/column/article/343335" target="_blank" rel="noreferrer">第6讲</a> 中介绍的 <strong>逻辑树</strong> 进行整理，也就是基于MECE原则逐层分解。</p><p>比如分析成本升高的问题，就可以把成本按照“固定成本/可变成本”的逻辑树先列出来，进一步分析到底是哪些项目上升导致的问题。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E7%9D%80%E9%AB%98%E6%89%8B%E5%AD%A6%E5%A4%8D%E7%9B%98/images/344511/6631e3f94a8fa187287835286f4aea3a.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E7%9D%80%E9%AB%98%E6%89%8B%E5%AD%A6%E5%A4%8D%E7%9B%98/images/344511/6631e3f94a8fa187287835286f4aea3a.jpg" alt=""></a></p><h2 id="对齐" tabindex="-1">对齐 <a class="header-anchor" href="#对齐" aria-label="Permalink to &quot;对齐&quot;">​</a></h2><p>对于自己团队内的目标和结果，我们可以独立地完成对比工作；但如果涉及跨部门的项目或者更大范围内的业务，我们可能无法把自己团队的结果与更高层次的目标直接进行对比，这时候就可以用另一个办法， <strong>对齐（Align）</strong>。</p><p><strong>对齐</strong> 是指，让里程碑型目标的结果要和公司战略目标的方向保持一致，或者说有直接的因果关系。无论是在一开始设定目标的时候，还是在复盘做事实比较的时候，对齐都特别的重要。</p><p>你还记得我在开篇词中讲的那个案例吗？我的一位朋友从用户运营做到了助理副总裁，他在公司做业务复盘的时候，提出把C2C模型改为B2C模型，然后自己内部创业去做MVP（Minimum Viable Product，最小化可用原型），并且采用OKR的方式来进行管理和沟通。</p><p>下面这张图展示了他的OKR规划：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E7%9D%80%E9%AB%98%E6%89%8B%E5%AD%A6%E5%A4%8D%E7%9B%98/images/344511/4f4002f77d16a91a4e42d2acf1106ec3.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E7%9D%80%E9%AB%98%E6%89%8B%E5%AD%A6%E5%A4%8D%E7%9B%98/images/344511/4f4002f77d16a91a4e42d2acf1106ec3.jpg" alt=""></a></p><p>内部创业的第一年，他并没有达成经营目标约定的数字（KR3）。但是在年底复盘的时候，他还是做出了一个结果—— <strong>成功打造了B2C的运营团队</strong>，这个很关键。</p><p>选品和客群有关（KR2），虽然客群选择出了偏差，但是他成功打造了B2C的运营团队，相当于解决了OKR中的两个关键结果（KR1&amp;KR4），流量转化率和交付满意度。他 <strong>对齐了“打造B2C直卖业务MVP”这个目标</strong>，依然算是取得了成功 <strong>。</strong></p><p>如果复盘的时候，他只是泛泛地说“锻炼了队伍”“开拓新业务”“打硬仗”之类的话，领导估计就不会买单给支持了。</p><p>所以事实比较的时候，需要找到 <strong>结果与战略目标之间的关系</strong>：</p><p>如果属于增强循环的因果关系，即使没有达成预定目标，依然不失为好结果。反之，如果结果和战略目标之间并没有这种关系（包括结果与战略目标是 <strong>反向关系</strong> 或 <strong>无关</strong>），就属于不好的结果。</p><h2 id="scqa架构" tabindex="-1">SCQA架构 <a class="header-anchor" href="#scqa架构" aria-label="Permalink to &quot;SCQA架构&quot;">​</a></h2><p>即使是好的结果，在复盘会议上把来龙去脉讲清楚，也很关键。这里，我介绍一个把事实讲清楚的方法， <strong>SCQA架构</strong>。</p><p>SCQA架构是结构化表达的一种语言范式，四个字母分别代笔 <strong>Situation（情境）</strong>、 <strong>Complication（冲突）、Question（问题）和Answer（答案）。</strong> 学会SCQA框架，会提升你表达的结构性，突出重点。</p><p>根据不同的目的或者表达重点，SCQA框架可以分为以下4种形式：标准式、开门见山式、突出忧虑式和突出信心式。你想强调什么，就先说什么。</p><h3 id="_1-标准式" tabindex="-1">1. 标准式 <a class="header-anchor" href="#_1-标准式" aria-label="Permalink to &quot;1\\. 标准式&quot;">​</a></h3><p>第1种是标准式，SCA，也就是情境-冲突-答案。这种形式适合一般的事实描述。</p><p>“你有没有遇到过这样的客户？她每天带孩子来体验你家的产品，孩子喜欢得不肯走，似乎觉得什么都好。但是最后要成交的时候，她又觉得价格贵了。”</p><p>这是在讲述“价格认知”这个概念的背景，也就是 <strong>S情境。</strong></p><p>“真的是因为她没钱吗？不一定，你可能会发现，她住的小区和开的车都很高档，因为 <strong>没钱和不舍得花钱</strong> 是两回事儿。那么有没有什么办法，可以让这些有钱却不舍得花钱的客户变得肯花钱呢？”</p><p>这是指出了一个和常识的不一样的地方，也就是 <strong>C冲突。</strong></p><p>“今天我来跟大家讲一下我遇到这类客户是怎么做转化的，看看对大家是否有帮助……”</p><p>这是给出了 <strong>A答案</strong>。</p><h3 id="_2-开门见山式" tabindex="-1">2. 开门见山式 <a class="header-anchor" href="#_2-开门见山式" aria-label="Permalink to &quot;2\\. 开门见山式&quot;">​</a></h3><p>第2种是开门见山式，ASC，也就是答案-情境-冲突。这种形式适合抛出自己的主张，得到大家的重视。</p><p>“我今天要向大家汇报一下我们的工作结果，关于把公司的C2C匹配模型改为B2C精品直卖模型的MVP构想。”</p><p>这是开门见山地直接给出自己的主张“改变平台模型”，也就是 <strong>A答案</strong>。</p><p>“公司从创始以来一直使用C2C平台匹配模型，一端是海量的产品，另一端是无限宽广的人群，平台靠收交易佣金做价值变现。”</p><p>这是描述之前的C2C匹配情况和商业模式，也就是 <strong>S情景</strong>。</p><p>“但是用户在我们的平台上并不清楚如何选择适合他们需求的产品，包括产品的品质如何，价位是否虚高，好评是不是由水军刷出来的。现实的结果是，虽然我们在流量端做了重金投入，但是只有极少数商家获得了高额营收，而绝大多数商家并没有太多成交量。这样下去，靠收交易佣金的平台模式很难取得成功，这两年的经营数据也证实了这一点。”</p><p>这是指出“实践证明C2C并没有解决客户问题”，也就是 <strong>C冲突。</strong></p><p>用“背景-冲突-答案”的开门见山式和团队沟通，你的第一句话，就是重点。</p><h3 id="_3-突出忧虑式" tabindex="-1">3. 突出忧虑式 <a class="header-anchor" href="#_3-突出忧虑式" aria-label="Permalink to &quot;3\\. 突出忧虑式&quot;">​</a></h3><p>第3种是突出忧虑式，CSA，也就是冲突-情境-答案。这种形式适合highlight问题，引发关注。</p><p>“哎呀，返券优惠再这么搞下去，公司就没有利润了，年底大家的奖金就泡汤了。”</p><p>听到这句话的时候，估计大家心里都要咯噔一下，这是 <strong>C冲突</strong>。</p><p>“还好，我们项目组做过一个新模式的数据分析以及小规模测试，如果按照我们的策略在全公司范围内推广，这个季度可以在不影响营收的前提下，降低折扣点。”</p><p>听到这句话，一颗悬到嗓子眼的心总算是放下来了，这就是 <strong>S情境。</strong></p><p>“目前还缺一个资深的运营经理，如果能来一个这样的人，我们有把握把返利降低10个点，这些都是利润。”</p><p>这是 <strong>A答案</strong>，要一个资深运营经理的head count，事情就搞定了。</p><p><strong>突出忧虑式</strong>，关键在于强调冲突，引导听众的忧虑，从而激发对背景的关注，和对答案的兴趣。</p><h3 id="_4-突出信心式" tabindex="-1">4. 突出信心式 <a class="header-anchor" href="#_4-突出信心式" aria-label="Permalink to &quot;4\\. 突出信心式&quot;">​</a></h3><p>第4种是突出信心式，QSCA，也就是问题-情境-冲突-答案。这种形式适合有创新想法向老板（广义的老板包括投资人、媒体等）申请政策和资源。</p><p>“今天全人类面临的最大威胁是什么？”</p><p>这是引发大家（投资人）对未来的思考，也就是 <strong>Q问题</strong>。</p><p>“在过去的几十年里，科技高速发展，人类拥有的先进武器可以摧毁地球几十次。”</p><p>这是现实情况，也就是 <strong>S情景</strong>。</p><p>“但是我们拥有了摧毁地球的能力，却没有逃离地球的方法。”</p><p>这是现存的矛盾，也就是 <strong>C冲突</strong>。</p><p>“所以，我们今天面临的最大威胁，是没有移民外星球的科技，我们公司将致力于私人航天技术，在可预见的未来，实现火星移民计划。”</p><p>这是 <strong>A答案</strong>。</p><p>上面这段话就是埃隆·马斯克说过的， <strong>火星移民计划</strong> 用这种表达框架来介绍，是不是突然觉得靠谱多了？试想一下，如果你用这样的框架在复盘的时候申请一个内部创业项目，是不是更有机会？</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>在这一讲，我为你介绍了在事实比较这一步快速比较目标与结果的方法。现在，我们回顾一下重点内容。</p><ol><li>事实包括两个部分，目标和结果。目标又可以分为数据型目标和里程碑型目标。</li><li>一个目标设定得好不好，主要看目标定性时是否与公司的战略对齐，定量时是否遵循SMART原则。</li><li>数据型目标的结果，可以用我总结的快速对比表格来对比；对于里程碑型目标的结果，可以遵循SCQA框架进行逻辑组织和表达，这样可以极大地提升复盘会议的参与度。</li></ol><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>这就是这一讲的全部内容了，最后留一道思考题给你。如果让你对现在或曾经负责的某个项目进行事实对比（里程碑型目标及其结果），你会采用SCQA框架中的哪种形式（SCQ/ASC/CSA/QSCA）来描述呢？请你试着描述一下，并说明选择这种形式的原因。</p><p>欢迎你把答案写在留言区，和我一起讨论。</p>',97)])])}const E=e(r,[["render",i]]);export{b as __pageData,E as default};
